// Chinese Zodiac data — animals, elements, years, and descriptions

export const ANIMALS = ['Rat', 'Ox', 'Tiger', 'Rabbit', 'Dragon', 'Snake', 'Horse', 'Goat', 'Monkey', 'Rooster', 'Dog', 'Pig'] as const
export const ELEMENTS = ['Wood', 'Fire', 'Earth', 'Metal', 'Water'] as const

export const ANIMAL_EMOJI: Record<string, string> = {
  Rat: '🐀', Ox: '🐂', Tiger: '🐅', Rabbit: '🐇', Dragon: '🐉', Snake: '🐍',
  Horse: '🐴', Goat: '🐐', Monkey: '🐒', Rooster: '🐓', Dog: '🐕', Pig: '🐖',
}

export function getChineseZodiac(year: number): { animal: string; element: string } {
  const animalIndex = (year - 4) % 12
  const elementIndex = Math.floor(((year - 4) % 10) / 2)
  return { animal: ANIMALS[animalIndex], element: ELEMENTS[elementIndex] }
}

export function getYearsForAnimal(animal: string): number[] {
  const idx = ANIMALS.indexOf(animal as typeof ANIMALS[number])
  if (idx === -1) return []
  const years: number[] = []
  for (let y = 1924; y <= 2043; y++) {
    if ((y - 4) % 12 === idx) years.push(y)
  }
  return years
}

