const MONTH_NAMES = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
]

export function formatCNYStart(year: number): string | null {
  const d = CNY_DATES[year]
  if (!d) return null
  return `${MONTH_NAMES[d[0] - 1]} ${d[1]}, ${year}`
}

export function formatCNYEnd(year: number): string | null {
  const next = CNY_DATES[year + 1]
  if (!next) return null
  const d = new Date(year + 1, next[0] - 1, next[1])
  d.setDate(d.getDate() - 1)
  return `${MONTH_NAMES[d.getMonth()]} ${d.getDate()}, ${year + 1}`
}

// Recent years mapped to animals (for SEO year pages)
export const YEAR_RANGE = Array.from({ length: 124 }, (_, i) => 1924 + i) // 1924-2047
